CALL {
  MATCH (p:Player)-[:playsFor]->(:Team {name: "Houston Rockets"})
  RETURN collect(DISTINCT p) AS players
}
CALL {
  MATCH (c)-[:receivesAward]->(:Award {name: "NBA Coach of the Year Award"})
  RETURN collect(DISTINCT c) AS coaches
}
WITH players + coaches AS allIndividuals
UNWIND allIndividuals AS person
RETURN count(DISTINCT person) AS playerCount
